var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{menus:[]},methods:{getData(){const a=window.location.origin+"/dashboard/persistent-menu/data";axios.get(a).then(a=>{this.menus=a.data}).catch(a=>{console.log(a)})},addNewMenu(){const a=window.location.origin+"/dashboard/persistent-menu";axios.post(a).then(a=>{this.menus=a.data}).catch(a=>{console.log(a)})},deleteMenu(a,b){const c=window.location.origin+"/dashboard/persistent-menu/"+b;axios.delete(c).then(b=>{this.menus.splice(a,1),this.$notify({group:"notification",type:b.data.status,title:b.data.title,text:b.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},updateData(a){const b=window.location.origin+"/dashboard/persistent-menu/"+this.menus[a].id;axios.post(b,{stype:this.menus[a].stype,title:this.menus[a].title,block:this.menus[a].block}).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},registerData(){const a=window.location.origin+"/dashboard/persistent-menu";axios.put(a).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},unregisterData(){const a=window.location.origin+"/dashboard/persistent-menu";axios.delete(a).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})}},created(){this.getData()}});